commit;

-- ---------------------------------------------------------------------------
-- Report
-- ---------------------------------------------------------------------------
declare
  l_docs pls_integer;
begin
  select count(*) into l_docs from inv_documents;
  sys.dbms_output.put_line('Documents in the inbox: ' || l_docs || '.');
  sys.dbms_output.put_line('Next: run 00_precheck.sql.');
end;
/
